import {test} from 'node:test';import assert from 'node:assert/strict';import {drafts} from '../src/drafts.mjs';import {apply} from '../src/editor.mjs';
test('cancel staged revision preserves published and unrelated draft',()=>{const s=drafts();s.stage('x','old');s.publish('x');s.stage('x','new');s.stage('y','keep');assert.equal(s.read().staged.x,'new');assert.deepEqual(apply(s,[{type:'cancel',id:'x'},{type:'cancel',id:'x'}]),[true,false]);assert.deepEqual(s.read(),{staged:{y:'keep'},published:{x:'old'}});});
test('invalid later action is atomic and empty is valid',()=>{const s=drafts();s.stage('x','a');assert.throws(()=>apply(s,[{type:'publish',id:'x'},{type:'oops',id:'x'}]),TypeError);assert.deepEqual(s.read(),{staged:{x:'a'},published:{}});assert.deepEqual(apply(s,[]),[]);});
test('mixed actions preserve order',()=>{const s=drafts();s.stage('a','A');s.stage('b','B');assert.deepEqual(apply(s,[{type:'cancel',id:'a'},{type:'publish',id:'a'},{type:'publish',id:'b'}]),[true,false,true]);assert.deepEqual(s.read(),{staged:{},published:{b:'B'}});});
